// us = movers; destination centre (cx,cy), facing (fx,fy); lat = sideways spacing wanted (drag lines); keep = hold slots at the slowest unit's pace
/* every selected unit that can move takes a place in the formation - infantry, vehicles, trucks, aircraft and boats (Abdullah 2026-11-14 18:15 "units can all form a formation") */
function fmApply(us,type,cx,cy,fx,fy,mode,keep,lat,wid){const m=us.filter(u=>u&&!u.isB&&u.s&&u.s.spd>0);const n=m.length;if(!n)return;
  if(!FM_TYPES.includes(type))type='line';const L=Math.hypot(fx,fy)||1;fx/=L;fy/=L;const px=-fy,py=fx,gnd=m,oth=[];
  const by={S:[],A:[],I:[],F:[],R:[]};for(const u of gnd)by[fmRole(u)].push(u);const cnt={};for(const r in by)cnt[r]=by[r].length;
  const sp=Math.max(18,...gnd.map(u=>u.r*2.6),20);const W=wid||Math.max(3,Math.ceil(Math.sqrt(gnd.length)*1.7));const S=fmLayout(type,cnt,sp,W,lat);
  let ox=0,oy=0;for(const u of gnd){ox+=u.x;oy+=u.y;}if(gnd.length){ox/=gnd.length;oy/=gnd.length;}
  let cap=Infinity;if(keep)for(const u of gnd)cap=Math.min(cap,u.s.spd);
  for(const r in by){const us2=by[r];if(!us2.length)continue;const sl=S[r].slice().sort((a,b)=>a[1]-b[1]||b[0]-a[0]);
    const q=us2.map(u=>[u,(u.x-ox)*px+(u.y-oy)*py]).sort((a,b)=>a[1]-b[1]||a[0].id-b[0].id);
    q.forEach(([u],i)=>{const k=sl[i];let x=cx+fx*k[0]+px*k[1],y=cy+fy*k[0]+py*k[1];setMove(u,x,y,mode);u.faceA=Math.atan2(fy,fx);u.sq=keep?1:0;if(keep&&isFinite(cap))u.order.cap=cap*.97;});}
  oth.sort((a,b)=>a.id-b.id).forEach((u,i)=>setMove(u,cx+px*(i-(oth.length-1)/2)*40,cy+py*(i-(oth.length-1)/2)*40,mode));}
// the AI sends its ground attack groups in a formation too: a wedge when armour leads, else a line
function aiForm(g,x,y){const cx=g.reduce((s,u)=>s+u.x,0)/g.length,cy=g.reduce((s,u)=>s+u.y,0)/g.length,nA=g.filter(u=>fmRole(u)==='A').length;
  if(g.length<3){formMove(g,x,y,'amove',1,4);return;}fmApply(g,nA*3>=g.length?'wedge':'line',x,y,x-cx,y-cy,'amove',true);}
// a goal the unit cannot reach (a formation slot in a pocket walled in by houses, on an island, across water) moves to the
// nearest spot it CAN reach, so it arrives there instead of waiting at the end of a half route (stuck units 2026-11-18)
function reachXY(u,x,y){const d=u.s.dom;if(d!=='ground'&&d!=='naval')return null;const s0=nearestPass(d,Math.floor(u.x/CELL),Math.floor(u.y/CELL)),g0=nearestPass(d,Math.floor(x/CELL),Math.floor(y/CELL));if(!s0||!g0)return null;
  const R=regions(d),rs=R[s0[1]*GW+s0[0]];if(!rs||R[g0[1]*GW+g0[0]]===rs)return null;const q=nearestInRegion(R,rs,g0[0],g0[1]);return q?[q[0]*CELL+CELL/2,q[1]*CELL+CELL/2]:null;}
function setMove(u,x,y,type){if(u.dgv||u.dgDig)return;if(u.s.dom!=='air'){const gb=u.s.dom==='ground',pb=P_B;if(gb){bocc();P_B=true;}let p;try{p=nearestPassXY(u.s.dom,x,y);}finally{P_B=pb;}/* a spot under a building (a slot that lands in the HQ) moves just outside it */if(p){x=p[0];y=p[1];}const q=reachXY(u,x,y);if(q){x=q[0];y=q[1];}}u.order={type,x,y};u.target=null;u.guard=null;u.path=null;u.ffx=null;if(u.kind==='jet'&&u.state!=='fly'){u.state='fly';u.landed=false;}}

/* ---------- combat ---------- */
// Spatial hash (rebuilt every tick) so target searches and vision only look at nearby cells, not every entity on the map.
const HC=160;let HW=Math.ceil(MAPW/HC)+2;
